import os

from keyword_list import keyword_list, infer_token_type

header = """// WARNING: This code was generated by python/generate_tokens.py
//
// DO NOT EDIT THIS CODE!!!
//
// Instead, make changes to python/generate_tokens.py and python/keyword_list.py
// and run the script to regenerate this code like this:
//
// cd python
// python3 generate_tokens.py
"""

footer = """// <--- END OF GENERATED CODE
"""

def workflow():
    target_path = os.path.join("..", "src", "scanner", "token.rs")

    prog = []
    
    with open(target_path, "r") as f:
        original = f.readlines()

    for line in original:
        if not line.startswith("// START OF GENERATED CODE --->"):
            prog.append(line)
            continue
        else:
            prog.append(line)
            break

    prog.append(header)
    for keyword in keyword_list:
        token_type = infer_token_type(keyword)
        prog.append(f"    {token_type},\n")
    prog.append(footer)
    
    fastforward = True
    for line in original:
        if fastforward:
            if line.startswith("// <--- END OF GENERATED CODE"):
                fastforward = False
            continue
        else:
            prog.append(line)
    
    with open(target_path, "w") as f:
        f.writelines(prog)
        

    

if __name__ == "__main__":
    workflow()